<template><section class="shop-page"><header class="shop-heading"><div><span class="shop-eyebrow">SEU COMÉRCIO, CONECTADO</span><h1>Visão geral da loja</h1><p>Acompanhe o catálogo e mantenha os dados de atendimento atualizados.</p></div><RouterLink class="shop-primary" to="/produtos?novo=1"><i class="ri-add-line"></i> Novo produto</RouterLink></header><div v-if="shop.error" class="shop-alert error" role="alert">{{shop.error}}</div><div class="shop-stats"><article v-for="card in cards" :key="card.label"><span>{{card.label}}<i :class="card.icon"></i></span><strong>{{String(card.count).padStart(2,'0')}}</strong><small>{{card.hint}}</small></article></div><div class="shop-welcome"><div><span class="shop-eyebrow">INFORMAÇÃO CERTA PARA CADA CLIENTE</span><h2>Seu catálogo dá voz à sua loja.</h2><p>Teste preços e disponibilidade antes de conectar o WhatsApp.</p></div><RouterLink to="/simulador" class="shop-primary">Testar atendimento <i class="ri-arrow-right-up-line"></i></RouterLink></div><div class="shop-dashboard-grid"><section class="shop-panel"><header class="shop-section-title"><h2>Últimos produtos atualizados</h2><RouterLink to="/produtos">Ver catálogo <i class="ri-arrow-right-line"></i></RouterLink></header><div v-for="p in recent" :key="p.id" class="shop-recent-row"><i class="ri-shopping-bag-3-line"></i><div><strong>{{p.name}}</strong><small>{{availability[p.availability]}} · {{p.sku}}</small></div><span>{{money(p.price_cents)}}</span></div><div v-if="!recent.length" class="shop-empty">Seu catálogo ainda está vazio.<br/><RouterLink to="/importacoes" class="shop-primary" style="margin-top:20px">Começar com uma NF-e</RouterLink></div></section><section class="shop-panel"><header class="shop-section-title"><h2>Disponibilidade do catálogo</h2><span class="shop-muted">{{shop.products.length}} produtos</span></header><div v-for="(label,status) in availability" :key="status" class="shop-availability-row" :class="{out:status==='OUT_OF_STOCK',discontinued:status==='DISCONTINUED'}"><div><span>{{label}}</span><strong>{{count(status)}}</strong></div><span><i :style="{width:(shop.products.length?count(status)/shop.products.length*100:0)+'%'}"></i></span></div><p class="shop-muted" style="padding:14px 22px 20px">Disponibilidade informada manualmente pelo comerciante. Não há contagem automática de estoque.</p></section></div><section class="shop-panel shop-dashboard-bottom"><header class="shop-section-title"><h2>Últimas alterações da loja</h2><RouterLink to="/historico">Ver histórico <i class="ri-arrow-right-line"></i></RouterLink></header><div v-for="event in shop.history.slice(0,4)" :key="event.id" class="shop-recent-row"><i class="ri-history-line"></i><div><strong>{{actions[event.action]||event.action}}<template v-if="event.after?.name"> · {{event.after.name}}</template></strong><small>{{event.actor}} · {{date(event.created_at)}}</small></div></div><div v-if="!shop.history.length" class="shop-empty">As próximas alterações aparecerão aqui.</div></section></section></template>
<script setup>
import { computed } from 'vue'
import { useShopStore } from '@/stores/shop.store'
import { availability,money,actions,date } from '@/utils/shop'
const shop=useShopStore()
const count=status=>shop.products.filter(p=>p.availability===status).length
const recent=computed(()=>[...shop.products].sort((a,b)=>b.updated_at.localeCompare(a.updated_at)).slice(0,4))
const cards=computed(()=>[{label:'Produtos no catálogo',count:shop.products.length,icon:'ri-box-3-line',hint:'O portfólio da sua loja'},{label:'Disponíveis',count:count('AVAILABLE'),icon:'ri-check-double-line',hint:'Prontos para oferecer'},{label:'Sem estoque',count:count('OUT_OF_STOCK'),icon:'ri-time-line',hint:'Aguardando reposição'},{label:'Notas importadas',count:shop.imports.filter(i=>i.confirmed_at).length,icon:'ri-file-check-line',hint:'Cadastros conferidos pela loja'}])
</script>
